function countVowelStrings(n) {
  // ways[v]: sorted strings of the current length whose last letter is vowel v.
  let ways = [1, 1, 1, 1, 1];
  for (let length = 2; length <= n; length++) {
    const next = [0, 0, 0, 0, 0];
    for (let v = 0; v < 5; v++) for (let u = 0; u <= v; u++) next[v] += ways[u];
    ways = next;
  }
  return ways.reduce((a, b) => a + b, 0);
}

