function generate(rand, size) {
  if (size === 'large') return [45 + Math.floor(rand() * 6)];
  // Mostly short lengths, sometimes anything up to the limit.
  return [rand() < 0.7 ? 1 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * 50)];
}
